<script setup lang="ts">
import { ref } from 'vue'
import { useAppStore } from '../../stores/appStore'
const { sessions, gradeRules, currentUser, addAuditLog } = useAppStore()
const storageKey = 'erp-system-settings'
const defaults = { systemName: 'Examination & Result Management System', universityName: 'BlueCrest University', contactEmail: '', defaultSessionId: sessions.value.find(session => session.status === 'active')?.id ?? '', defaultSemester: '1', resultNotice: true, sessionTimeout: 30 }
const saved = localStorage.getItem(storageKey)
const settings = ref({ ...defaults, ...(saved ? JSON.parse(saved) : {}) })
const message = ref('')
function saveSettings() { if (currentUser.value?.role !== 'admin') { message.value = 'Only administrators can save system settings.'; return }; if (!settings.value.systemName.trim() || !settings.value.universityName.trim() || settings.value.sessionTimeout < 5) { message.value = 'Enter valid system details and a session timeout of at least 5 minutes.'; return }; localStorage.setItem(storageKey, JSON.stringify(settings.value)); addAuditLog('UPDATE_SETTINGS', 'SystemSettings', 'Updated system configuration'); message.value = 'Settings saved successfully.'; setTimeout(() => { message.value = '' }, 3000) }
</script>
<template>
  <div class="space-y-5"><div><p class="text-xs font-medium uppercase tracking-wider text-gold-600">Administration</p><h2 class="font-serif text-2xl font-semibold text-navy-900">System Settings</h2><p class="text-sm text-navy-500">Configure system-level defaults without changing academic records or grading logic.</p></div><div v-if="message" class="rounded-lg border border-gold-200 bg-gold-50 px-4 py-3 text-sm text-gold-700">{{ message }}</div><form class="space-y-5" @submit.prevent="saveSettings"><section class="rounded-xl border border-navy-100 bg-white p-5"><h3 class="mb-4 font-serif font-semibold text-navy-900">General Settings</h3><div class="grid gap-4 md:grid-cols-2"><label class="text-sm text-navy-700">System Name<input v-model="settings.systemName" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm" /></label><label class="text-sm text-navy-700">University Name<input v-model="settings.universityName" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm" /></label><label class="text-sm text-navy-700">Contact Email<input v-model="settings.contactEmail" type="email" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm" placeholder="office@example.edu" /></label></div></section><section class="rounded-xl border border-navy-100 bg-white p-5"><h3 class="mb-4 font-serif font-semibold text-navy-900">Academic Defaults</h3><div class="grid gap-4 md:grid-cols-2"><label class="text-sm text-navy-700">Default Academic Session<select v-model="settings.defaultSessionId" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm"><option v-for="session in sessions" :key="session.id" :value="session.id">{{ session.name }}</option></select></label><label class="text-sm text-navy-700">Default Semester<input v-model="settings.defaultSemester" type="number" min="1" max="12" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm" /></label></div><div class="mt-4 rounded-lg bg-navy-50 p-3 text-xs text-navy-600">The active grading system currently contains {{ gradeRules.length }} configured rules. Grading calculations remain controlled by the existing calculation utilities.</div></section><section class="rounded-xl border border-navy-100 bg-white p-5"><h3 class="mb-4 font-serif font-semibold text-navy-900">Security & Result Behavior</h3><div class="grid gap-4 md:grid-cols-2"><label class="text-sm text-navy-700">Session Timeout (minutes)<input v-model.number="settings.sessionTimeout" type="number" min="5" max="480" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2.5 text-sm" /></label><label class="flex items-center gap-2 self-end pb-3 text-sm text-navy-700"><input v-model="settings.resultNotice" type="checkbox" /> Show result publication notice</label></div><p class="mt-3 text-xs text-navy-400">Session timeout is stored as a configuration preference. Enforcement will be connected to backend authentication in a later security phase.</p></section><button type="submit" class="rounded-lg bg-navy-800 px-5 py-2.5 text-sm font-medium text-white" :disabled="currentUser?.role !== 'admin'">Save Settings</button></form></div>
</template>
